8	public class ProductQueryService(AppDbContext db)
9	{
10	    private const int PageSize = 20;
11	
12	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(int page, string? categoryId = null, string? subcategoryId = null, string? sortBy = null, string? sortDirection = null, string? search = null)
13	    {
14	        page = page < 1 ? 1 : page;
15	
16	        IQueryable<Product> query = db.Products.Include(p => p.Subcategory);
17	
18	        if (!string.IsNullOrEmpty(subcategoryId))
19	        {
20	            query = query.Where(p => p.SubcategoryId == subcategoryId);
21	        }
22	        else if (!string.IsNullOrEmpty(categoryId))
23	        {
24	            query = query.Where(p => p.Subcategory!.CategoryId == categoryId);
25	        }
26	
27	        if (!string.IsNullOrEmpty(search))
28	        {
29	            var loweredSearch = search.ToLower();
30	            query = query.Where(p => p.Name.ToLower().Contains(loweredSearch) || p.Description.ToLower().Contains(loweredSearch));
31	        }
32	
33	        var totalCount = await query.CountAsync();
34	
35	        // long arithmetic + clamp to totalCount avoids an int overflow into a negative
36	        // Skip() for very large page values while preserving "beyond last page -> empty" behavior.
37	        var skip = (int)Math.Min((long)(page - 1) * PageSize, totalCount);
38	
39	        var descending = sortDirection == "desc";
